<?php

declare(strict_types=1);
require __DIR__ . DIRECTORY_SEPARATOR . 'config.php';
require_admin();
$plans=subscription_plans(); $selectedSlug=(string)($_GET['plan']??$_POST['original_slug']??''); $selected=null; foreach($plans as $plan) if(($plan['slug']??'')===$selectedSlug)$selected=$plan;
$error=''; $notice=(string)($_GET['notice']??'');
if($_SERVER['REQUEST_METHOD']==='POST') try {
